def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    border_counts = Counter(
        grid[r][c]
        for r in range(h)
        for c in {0, w - 1}
        if grid[r][c] != bg
    )
    if not border_counts:
        return [row[:] for row in grid]
    wall = border_counts.most_common(1)[0][0]

    def edge_runs(col):
        runs = []
        r = 0
        while r < h:
            if grid[r][col] == wall:
                start = r
                while r < h and grid[r][col] == wall:
                    r += 1
                runs.append((start, r))
            else:
                r += 1
        return runs

    left_runs = edge_runs(0)
    right_runs = edge_runs(w - 1)
    pairs = [(l, r) for l in left_runs for r in right_runs
             if l[1] - l[0] == r[1] - r[0]]
    if not pairs:
        return [row[:] for row in grid]

    non_bg = [v for v in counts if v != bg and v != wall]
    if not non_bg:
        return [row[:] for row in grid]
    seed_color = non_bg[0]
    seeds = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == seed_color]

    # Find the boundary run whose rows contain the seed pattern.
    candidates = []
    for left, right in pairs:
        for r, c in seeds:
            if left[0] <= r < left[1]:
                candidates.append((left, right, 0))
            if right[0] <= r < right[1]:
                candidates.append((right, left, w - 1))
    if not candidates:
        return [row[:] for row in grid]

    source, target, source_col = candidates[0]
    target_col = w - 1 if source_col == 0 else 0
    active_offsets = {
        r - source[0] for r, c in seeds
        if source[0] <= r < source[1]
    }

    out = [row[:] for row in grid]

    # Fill from each seed toward its boundary wall and mark the seed.
    for r, c in seeds:
        if source[0] <= r < source[1]:
            step = -1 if source_col == 0 else 1
            x = c + step
            while 0 <= x < w and x != source_col:
                out[r][x] = seed_color
                x += step
            out[r][c] = 4

    # Copy the active row offsets across to the opposite boundary run.
    for offset in active_offsets:
        r = target[0] + offset
        if r >= target[1]:
            continue
        if any(sr == r for sr, _ in seeds):
            continue
        for c in range(w):
            if c != target_col:
                out[r][c] = seed_color

    return out
